# Node.js 开发实战

Node.js 是现代 Web 开发的核心技术。通过本教程，你将学会使用 OpenClaw 构建 Node.js 应用，从简单的 API 到完整的后端服务。

## 为什么选择 Node.js？

Node.js 在后端开发中的优势：

- **统一语言**: 前后端都使用 JavaScript
- **高性能**: 基于 V8 引擎，事件驱动架构
- **丰富生态**: npm 提供超过 200 万个包
- **实时应用**: 天然支持 WebSocket 和实时通信
- **微服务**: 轻量级，适合微服务架构

## 准备工作

### 安装 Node.js 技能

```bash
npx clawhub@latest install nodejs
```

### 验证 Node.js 环境

```bash
# 检查 Node.js 版本
node --version

# 检查 npm 版本
npm --version

# 测试 OpenClaw Node.js 技能
openclaw test nodejs
```

## 创建 Express.js 应用

### 初始化项目

```
创建新的 Node.js 项目，使用 Express.js 框架
```

AI 将执行以下步骤：

```bash
# 1. 创建项目目录
mkdir my-express-app
cd my-express-app

# 2. 初始化 npm 项目
npm init -y

# 3. 安装 Express
npm install express

# 4. 创建入口文件
touch server.js
```

### 创建基本服务器

```
创建 Express 服务器，监听 3000 端口，返回 "Hello World"
```

AI 将生成 `server.js`：

```javascript
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// 中间件：解析 JSON
app.use(express.json());

// 根路由
app.get('/', (req, res) => {
  res.json({
    message: 'Hello World!',
    timestamp: new Date().toISOString()
  });
});

// 启动服务器
app.listen(PORT, () => {
  console.log(`服务器运行在 http://localhost:${PORT}`);
});
```

## RESTful API 设计

### 创建 CRUD API

```
创建用户管理 API，包含增删改查操作
```

AI 将生成完整的 API 代码：

```javascript
const express = require('express');
const app = express();
app.use(express.json());

// 模拟数据库
let users = [
  { id: 1, name: '张三', email: 'zhangsan@example.com' },
  { id: 2, name: '李四', email: 'lisi@example.com' }
];
let nextId = 3;

// GET /users - 获取所有用户
app.get('/users', (req, res) => {
  res.json(users);
});

// GET /users/:id - 获取单个用户
app.get('/users/:id', (req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));
  if (!user) {
    return res.status(404).json({ error: '用户不存在' });
  }
  res.json(user);
});

// POST /users - 创建新用户
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // 验证输入
  if (!name || !email) {
    return res.status(400).json({ error: '姓名和邮箱不能为空' });
  }

  const newUser = {
    id: nextId++,
    name,
    email,
    createdAt: new Date().toISOString()
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// PUT /users/:id - 更新用户
app.put('/users/:id', (req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));
  if (!user) {
    return res.status(404).json({ error: '用户不存在' });
  }

  const { name, email } = req.body;
  if (name) user.name = name;
  if (email) user.email = email;
  user.updatedAt = new Date().toISOString();

  res.json(user);
});

// DELETE /users/:id - 删除用户
app.delete('/users/:id', (req, res) => {
  const userIndex = users.findIndex(u => u.id === parseInt(req.params.id));
  if (userIndex === -1) {
    return res.status(404).json({ error: '用户不存在' });
  }

  users.splice(userIndex, 1);
  res.status(204).send();
});

// 404 处理
app.use((req, res) => {
  res.status(404).json({ error: '路由不存在' });
});

// 错误处理
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: '服务器错误' });
});

app.listen(3000, () => {
  console.log('服务器运行在 http://localhost:3000');
});
```

## 数据库集成

### 使用 MongoDB

```
集成 MongoDB，创建用户模型和 API
```

AI 将生成完整的 MongoDB 集成代码：

```javascript
const express = require('express');
const mongoose = require('mongoose');
const app = express();
app.use(express.json());

// 连接 MongoDB
mongoose.connect('mongodb://localhost:27017/myapp', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// 定义用户模型
const userSchema = new mongoose.Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  createdAt: { type: Date, default: Date.now }
});

const User = mongoose.model('User', userSchema);

// GET /users - 获取所有用户
app.get('/users', async (req, res) => {
  try {
    const users = await User.find();
    res.json(users);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /users/:id - 获取单个用户
app.get('/users/:id', async (req, res) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) {
      return res.status(404).json({ error: '用户不存在' });
    }
    res.json(user);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /users - 创建新用户
app.post('/users', async (req, res) => {
  try {
    const user = new User(req.body);
    await user.save();
    res.status(201).json(user);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// PUT /users/:id - 更新用户
app.put('/users/:id', async (req, res) => {
  try {
    const user = await User.findByIdAndUpdate(
      req.params.id,
      req.body,
      { new: true, runValidators: true }
    );
    if (!user) {
      return res.status(404).json({ error: '用户不存在' });
    }
    res.json(user);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// DELETE /users/:id - 删除用户
app.delete('/users/:id', async (req, res) => {
  try {
    const user = await User.findByIdAndDelete(req.params.id);
    if (!user) {
      return res.status(404).json({ error: '用户不存在' });
    }
    res.status(204).send();
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('服务器运行在 http://localhost:3000');
});
```

### 使用 PostgreSQL

```
使用 pg 库连接 PostgreSQL 数据库
```

AI 将生成 PostgreSQL 集成代码：

```javascript
const express = require('express');
const { Pool } = require('pg');
const app = express();
app.use(express.json());

// 创建连接池
const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'myapp',
  password: 'your_password',
  port: 5432
});

// 创建表
pool.query(`
  CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  )
`).catch(err => console.error(err));

// GET /users
app.get('/users', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM users ORDER BY id');
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /users/:id
app.get('/users/:id', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM users WHERE id = $1',
      [req.params.id]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: '用户不存在' });
    }
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /users
app.post('/users', async (req, res) => {
  const { name, email } = req.body;
  try {
    const result = await pool.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    res.status(201).json(result.rows[0]);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('服务器运行在 http://localhost:3000');
});
```

## 错误处理和验证

### 输入验证中间件

```
创建输入验证中间件，确保数据有效性
```

AI 将生成验证中间件：

```javascript
const express = require('express');
const app = express();
app.use(express.json());

// 验证中间件
const validateUser = (req, res, next) => {
  const { name, email } = req.body;

  const errors = [];

  if (!name || typeof name !== 'string' || name.length < 2) {
    errors.push('姓名必须是至少 2 个字符的字符串');
  }

  if (!email || typeof email !== 'string') {
    errors.push('邮箱不能为空');
  } else {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      errors.push('邮箱格式不正确');
    }
  }

  if (errors.length > 0) {
    return res.status(400).json({ errors });
  }

  next();
};

// 使用验证中间件
app.post('/users', validateUser, (req, res) => {
  const { name, email } = req.body;
  // 创建用户逻辑...
  res.status(201).json({ name, email });
});

// 异步错误处理包装器
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/users', asyncHandler(async (req, res) => {
  const users = await User.find();
  res.json(users);
}));

// 全局错误处理
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({
    error: err.message || '服务器错误'
  });
});
```

## 实战案例

### 案例 1：构建博客 API

目标：创建完整的博客后端 API

```
创建博客 API，包含文章、评论和用户管理
```

AI 将生成完整的博客 API 结构：

```javascript
// models/Article.js
const mongoose = require('mongoose');

const articleSchema = new mongoose.Schema({
  title: { type: String, required: true },
  content: { type: String, required: true },
  author: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  tags: [String],
  views: { type: Number, default: 0 },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now }
});

articleSchema.index({ title: 'text', content: 'text' });

module.exports = mongoose.model('Article', articleSchema);

// routes/articles.js
const express = require('express');
const router = express.Router();
const Article = require('../models/Article');

// GET /api/articles - 获取所有文章
router.get('/', async (req, res) => {
  try {
    const { page = 1, limit = 10, tag } = req.query;

    const query = tag ? { tags: tag } : {};

    const articles = await Article.find(query)
      .populate('author', 'name email')
      .sort({ createdAt: -1 })
      .limit(limit * 1)
      .skip((page - 1) * limit);

    const total = await Article.countDocuments(query);

    res.json({
      articles,
      page: parseInt(page),
      pages: Math.ceil(total / limit),
      total
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/articles/:id - 获取单篇文章
router.get('/:id', async (req, res) => {
  try {
    const article = await Article.findById(req.params.id)
      .populate('author', 'name email');

    if (!article) {
      return res.status(404).json({ error: '文章不存在' });
    }

    // 增加浏览次数
    article.views += 1;
    await article.save();

    res.json(article);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/articles - 创建文章
router.post('/', async (req, res) => {
  try {
    const article = new Article({
      ...req.body,
      author: req.user.id // 假设已通过认证中间件
    });
    await article.save();
    res.status(201).json(article);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

module.exports = router;
```

### 案例 2：文件上传 API

目标：实现文件上传和处理功能

```
创建文件上传 API，支持图片上传和缩略图生成
```

AI 将生成文件上传代码：

```javascript
const express = require('express');
const multer = require('multer');
const sharp = require('sharp');
const path = require('path');
const fs = require('fs');

const app = express();

// 配置存储
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = 'uploads/';
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});

// 文件过滤器
const fileFilter = (req, file, cb) => {
  const allowedTypes = /jpeg|jpg|png|gif/;
  const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
  const mimetype = allowedTypes.test(file.mimetype);

  if (extname && mimetype) {
    cb(null, true);
  } else {
    cb(new Error('只支持图片文件'));
  }
};

const upload = multer({
  storage,
  limits: { fileSize: 5 * 1024 * 1024 }, // 5MB
  fileFilter
});

// 单文件上传
app.post('/upload', upload.single('image'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: '没有上传文件' });
    }

    // 生成缩略图
    const thumbnailPath = `uploads/thumb-${req.file.filename}`;
    await sharp(req.file.path)
      .resize(200, 200, { fit: 'cover' })
      .toFile(thumbnailPath);

    res.json({
      original: req.file.filename,
      thumbnail: `thumb-${req.file.filename}`,
      size: req.file.size
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 多文件上传
app.post('/upload/multiple', upload.array('images', 5), async (req, res) => {
  try {
    if (!req.files || req.files.length === 0) {
      return res.status(400).json({ error: '没有上传文件' });
    }

    const files = await Promise.all(req.files.map(async (file) => {
      const thumbnailPath = `uploads/thumb-${file.filename}`;
      await sharp(file.path)
        .resize(200, 200, { fit: 'cover' })
        .toFile(thumbnailPath);

      return {
        original: file.filename,
        thumbnail: `thumb-${file.filename}`,
        size: file.size
      };
    }));

    res.json({ files });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
```

