## 快速笔记收集

### 创建快速笔记

```
创建快速笔记函数，支持多种格式输入
```

AI 将生成笔记收集代码：

```python
import os
from notion_client import Client
from datetime import datetime
import json
from dotenv import load_dotenv

load_dotenv()

class QuickNote:
    def __init__(self):
        self.notion = Client(auth=os.getenv('NOTION_API_KEY'))
        self.database_id = os.getenv('NOTION_DATABASE_ID')

    def create_note(self, title, content, tags=None, category='General'):
        """
        创建快速笔记

        参数:
            title: 笔记标题
            content: 笔记内容
            tags: 标签列表
            category: 笔记类别
        """

        # 构建页面属性
        page_properties = {
            "Title": {
                "title": [
                    {
                        "text": {
                            "content": title
                        }
                    }
                ]
            },
            "Category": {
                "select": {
                    "name": category
                }
            },
            "Created": {
                "date": {
                    "start": datetime.now().isoformat()
                }
            }
        }

        # 添加标签
        if tags:
            page_properties["Tags"] = {
                "multi_select": [{"name": tag} for tag in tags]
            }

        # 创建页面
        try:
            new_page = self.notion.pages.create(
                parent={"database_id": self.database_id},
                properties=page_properties
            )

            # 添加内容
            if content:
                self.notion.blocks.children.append(
                    block_id=new_page["id"],
                    children=[
                        {
                            "object": "block",
                            "type": "paragraph",
                            "paragraph": {
                                "rich_text": [
                                    {
                                        "type": "text",
                                        "text": {
                                            "content": content
                                        }
                                    }
                                ]
                            }
                        }
                    ]
                )

            print(f"笔记创建成功: {title}")
            return new_page

        except Exception as e:
            print(f"创建笔记失败: {e}")
            return None

    def create_meeting_note(self, title, attendees, agenda, notes, action_items=None):
        """创建会议笔记"""

        # 创建会议笔记页面
        page = self.create_note(
            title=f"会议 - {title}",
            content="",
            category="Meeting",
            tags=["meeting", "notes"]
        )

        if page:
            page_id = page["id"]

            # 构建会议笔记结构
            children = [
                # 会议信息
                {
                    "object": "block",
                    "type": "heading_2",
                    "heading_2": {
                        "rich_text": [{"text": {"content": "📅 会议信息"}}]
                    }
                },
                {
                    "object": "block",
                    "type": "paragraph",
                    "paragraph": {
                        "rich_text": [
                            {"text": {"content": f"日期: {datetime.now().strftime('%Y-%m-%d')}\n"}},
                            {"text": {"content": f"参会者: {', '.join(attendees)}"}}
