```python
import re
from collections import Counter

class NoteOrganizer:
    def __init__(self, notion_client):
        self.notion = notion_client

        # 定义分类规则
        self.category_rules = {
            '技术': ['编程', '开发', '代码', 'API', '算法', 'Python', 'JavaScript', 'Docker'],
            '工作': ['会议', '项目', '任务', '报告', '计划'],
            '学习': ['教程', '课程', '笔记', '复习', '考试'],
            '生活': ['购物', '旅行', '健康', '运动'],
            '灵感': ['想法', '创意', '设计', '创新']
        }

        self.tag_keywords = {
            'Python': ['python', '.py', 'pip'],
            'JavaScript': ['javascript', 'js', 'node', 'npm'],
            'Docker': ['docker', 'container', '镜像'],
            '数据库': ['sql', 'database', 'query', 'mysql', 'postgresql'],
            '前端': ['html', 'css', 'react', 'vue', '前端'],
            '后端': ['api', 'server', 'backend', '后端'],
            'DevOps': ['deploy', 'ci/cd', 'jenkins', '部署']
        }

    def classify_note(self, title, content):
        """根据内容分类笔记"""
        text = f"{title} {content}".lower()

        # 统计各类别匹配数
        category_scores = {}
        for category, keywords in self.category_rules.items():
            score = sum(1 for keyword in keywords if keyword.lower() in text)
            if score > 0:
                category_scores[category] = score

        # 返回得分最高的类别
        if category_scores:
            return max(category_scores, key=category_scores.get)

        return 'General'

    def extract_tags(self, title, content):
        """从内容中提取标签"""
        text = f"{title} {content}"  

        detected_tags = []

        # 检查每个标签关键词
        for tag, keywords in self.tag_keywords.items():
            for keyword in keywords:
                if keyword.lower() in text.lower():
                    detected_tags.append(tag)
                    break

        # 使用正则提取代码块标签
        code_blocks = re.findall(r'```(\w+)', text)
        detected_tags.extend(code_blocks)

        return list(set(detected_tags))

    def organize_note(self, page_id):
        """整理单个笔记"""
        try:
            # 获取页面内容
            page = self.notion.pages.retrieve(page_id=page_id)

            # 获取页面内容块
            blocks = self.notion.blocks.children.list(block_id=page_id)

            # 提取文本内容
            title = self._extract_title(page)
            content = self._extract_content(blocks)

            # 自动分类
            category = self.classify_note(title, content)

            # 提取标签
            tags = self.extract_tags(title, content)

            # 更新页面属性
            properties = {
                "Category": {"select": {"name": category}}
            }

            if tags:
                properties["Tags"] = {
                    "multi_select": [{"name": tag} for tag in tags]
                }

            self.notion.pages.update(
                page_id=page_id,
                properties=properties
            )

            print(f"已整理: {title} -> {category}")
            print(f"标签: {', '.join(tags)}")

            return True

        except Exception as e:
            print(f"整理失败: {e}")
            return False

    def _extract_title(self, page):
        """提取页面标题"""
        title_prop = page['properties'].get('Title', {})
        if 'title' in title_prop:
            return title_prop['title'][0]['text']['content']
        return 'Untitled'

    def _extract_content(self, blocks):
        """提取所有文本内容"""
        content_parts = []

        for block in blocks['results']:
            if 'paragraph' in block:
                text = block['paragraph']['text']
                content_parts.extend([t['text']['content'] for t in text])
            elif 'heading_2' in block:
                text = block['heading_2']['text']
                content_parts.extend([t['text']['content'] for t in text])
            elif 'code' in block:
                text = block['code']['text']
                content_parts.extend([t['text']['content'] for t in text])

        return ' '.join(content_parts)

# 使用示例
if __name__ == "__main__":
    note_taker = QuickNote()
    organizer = NoteOrganizer(note_taker.notion)

    # 创建一个新笔记
    page = note_taker.create_note(
        title="使用 Docker 部署 Python 应用",
        content="本教程介绍如何使用 Docker 容器化 Python 应用..."
    )

    if page:
        # 自动整理笔记
        organizer.organize_note(page['id'])
