    def create_from_template(self, template_name, **kwargs):
        """从模板创建笔记"""

        if template_name not in self.templates:
            print(f"模板 '{template_name}' 不存在")
            return None

        template = self.templates[template_name]

        # 格式化标题
        title = template['title'].format(**kwargs)

        # 创建页面
        page = self.note_taker.create_note(
            title=title,
            content='',
            category=template['category'],
            tags=template['tags']
        )

        if page:
            page_id = page['id']

            # 构建内容块
            children = []

            for item in template['structure']:
                block = self._create_block(item)
                if block:
                    children.append(block)

            # 添加到页面
            self.note_taker.notion.blocks.children.append(
                block_id=page_id,
                children=children
            )

            print(f"已从模板创建笔记: {title}")
            return page

        return None

    def _create_block(self, item):
        """创建内容块"""
        block_type = item['type']

        if block_type == 'heading_2':
            return {
                "object": "block",
                "type": "heading_2",
                "heading_2": {
                    "rich_text": [{
                        "type": "text",
                        "text": {"content": item['text']}
                    }]
                }
            }

        elif block_type == 'paragraph':
            placeholder = item.get('placeholder', '')
            return {
                "object": "block",
                "type": "paragraph",
                "paragraph": {
                    "rich_text": [{
                        "type": "text",
                        "text": {"content": placeholder}
                    }]
                }
            }

        elif block_type == 'bulleted_list':
            return {
                "object": "block",
                "type": "bulleted_list_item",
                "bulleted_list_item": {
                    "rich_text": [{
                        "type": "text",
                        "text": {"content": ""}
                    }]
                }
            }

        elif block_type == 'code':
            language = item.get('language', 'text')
            return {
                "object": "block",
                "type": "code",
                "code": {
                    "rich_text": [{
                        "type": "text",
                        "text": {"content": "# 在这里输入代码"}
                    }],
                    "language": language
                }
            }

        return None

