        return self.templates.create_from_template(
            'learning_log',
            topic=topic,
            date=datetime.now().strftime('%Y-%m-%d')
        )

    def review_weekly_notes(self):
        """每周复习笔记"""
        notes = self.search.get_recent_notes(days=7)

        # 创建周总结
        summary_title = f"周学习总结 - {datetime.now().strftime('%Y年第%W周')}"

        categories = {}
        for note in notes:
            category = note['category']
            if category not in categories:
                categories[category] = []
            categories[category].append(note['title'])

        # 构建总结内容
        content = "本周学习内容汇总：\n\n"
        for category, titles in categories.items():
            content += f"\n{category}:\n"
            for title in titles:
                content += f"- {title}\n"

        self.note_taker.create_note(
            title=summary_title,
            content=content,
            category='复习',
            tags=['周总结', '复习']
        )

    def auto_organize_all_notes(self):
        """自动整理所有笔记"""
        # 获取所有笔记
        results = self.note_taker.notion.databases.query(
            database_id=self.note_taker.database_id
        )

        for page in results['results']:
            self.organizer.organize_note(page['id'])

