class StrongConsistencyStore:
    def write(self, key, value):
        # 同步复制到所有节点
        for node in self.nodes:
            node.write(key, value)
        return True

    def read(self, key):
        # 从任何节点读取都返回最新值
        return self.quorum_read(key)

# 可用性（Availability）示例
