# 两阶段提交协议
class TwoPhaseCommit:
    def prepare(self, participants):
        # 阶段 1：准备
        responses = []
        for p in participants:
            response = p.prepare_transaction()
            responses.append(response)

        if all(r == 'ready' for r in responses):
            # 阶段 2：提交
            for p in participants:
                p.commit()
            return True
        else:
            # 阶段 2：回滚
            for p in participants:
                p.rollback()
            return False

# Saga 模式（长事务）
class SagaOrchestrator:
    def execute(self, transactions):
        completed = []
        try:
            for tx in transactions:
                tx.execute()
                completed.append(tx)
            return True
        except Exception:
            # 补偿事务
            for tx in reversed(completed):
                tx.compensate()
            return False
```

## 最终一致性

```python
import asyncio
from typing import Dict, List

class EventualConsistencyStore:
    def __init__(self, node_id: str, replicas: List[str]):
        self.node_id = node_id
        self.replicas = replicas
        self.data: Dict = {}
        self.vector_clock = {}

    async def write(self, key: str, value):
        # 更新向量时钟
        self.vector_clock[key] = self.vector_clock.get(key, {})
        self.vector_clock[key][self.node_id] = \
            self.vector_clock[key].get(self.node_id, 0) + 1

        # 写入本地
        self.data[key] = {
            'value': value,
            'vector_clock': self.vector_clock[key].copy(),
            'timestamp': time.time()
        }

        # 异步复制到其他节点
        asyncio.create_task(self._replicate(key, value))

    async def _replicate(self, key: str, value):
        for replica in self.replicas:
            try:
                await self._send_to_replica(replica, key, value)
            except Exception as e:
                logger.error(f"Failed to replicate to {replica}: {e}")

    async def read(self, key: str) -> any:
        # 读取本地数据
        local_version = self.data.get(key)
        if not local_version:
            # 从其他节点获取
            return await self._read_from_replicas(key)
        return local_version['value']
```

## 实战案例：分布式锁

```python
import redis
from contextlib import contextmanager

class DistributedLock:
    def __init__(self, redis_client: redis.Redis, lock_key: str):
        self.redis = redis_client
        self.lock_key = lock_key
        self.lock_value = None

    @contextmanager
    def acquire(self, timeout: int = 30, auto_release: int = 60):
        self.lock_value = f"lock:{uuid.uuid4()}"

        # 尝试获取锁
        acquired = self.redis.set(
            self.lock_key,
            self.lock_value,
            nx=True,
            ex=auto_release
        )

        if not acquired:
            raise LockAcquisitionError(f"Could not acquire lock: {self.lock_key}")

        try:
            yield self
        finally:
            # 释放锁（使用 Lua 脚本保证原子性）
            self._release_lock()

    def _release_lock(self):
        lua_script = """
        if redis.call("get", KEYS[1]) == ARGV[1] then
            return redis.call("del", KEYS[1])
        else
            return 0
        end
        """
        self.redis.eval(lua_script, 1, self.lock_key, self.lock_value)

# 使用示例
lock = DistributedLock(redis_client, "critical_section")

with lock.acquire(timeout=10, auto_release=30):
    # 执行关键代码
    perform_critical_operation()
```

## 实战案例：分布式缓存

```python
class DistributedCache:
    def __init__(self, nodes: List[str]):
        self.nodes = nodes
        self.hash_ring = ConsistentHashRing(nodes)

    def get(self, key: str):
        node = self.hash_ring.get_node(key)
        return self._get_from_node(node, key)

    def set(self, key: str, value: any, ttl: int = 3600):
        node = self.hash_ring.get_node(key)
        return self._set_to_node(node, key, value, ttl)

    def invalidate(self, key: str):
        # 使所有节点上的缓存失效
        node = self.hash_ring.get_node(key)
        self._invalidate_node(node, key)

        # 广播失效消息
        self._broadcast_invalidation(key)

class ConsistentHashRing:
    def __init__(self, nodes: List[str], replicas: int = 150):
        self.ring = {}
        self.replicas = replicas
        self.sorted_keys = []

        for node in nodes:
            self.add_node(node)

    def add_node(self, node: str):
        for i in range(self.replicas):
            virtual_node = f"{node}:{i}"
            key = self._hash(virtual_node)
            self.ring[key] = node
            self.sorted_keys.append(key)

        self.sorted_keys.sort()

    def get_node(self, key: str) -> str:
        if not self.ring:
            return None

        key_hash = self._hash(key)

        # 找到顺时针方向第一个节点
        for ring_key in self.sorted_keys:
            if ring_key >= key_hash:
                return self.ring[ring_key]

        # 环绕到第一个节点
        return self.ring[self.sorted_keys[0]]

    @staticmethod
    def _hash(key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)
```

