## 数据加密

```python
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2
import os

class EncryptionManager:
    def __init__(self, password: str, salt: bytes = None):
        self.salt = salt or os.urandom(16)
        self.key = self._derive_key(password)
        self.cipher = Fernet(self.key)

    def _derive_key(self, password: str) -> bytes:
        kdf = PBKDF2(
            algorithm=hashes.SHA256(),
            length=32,
            salt=self.salt,
            iterations=100000,
        )
        return kdf.derive(password.encode())

    def encrypt(self, data: str) -> bytes:
        return self.cipher.encrypt(data.encode())

    def decrypt(self, encrypted_data: bytes) -> str:
        return self.cipher.decrypt(encrypted_data).decode()

# 使用示例
manager = EncryptionManager('strong-password')
encrypted = manager.encrypt('sensitive data')
decrypted = manager.decrypt(encrypted)

# 数据库字段加密
class SecureField:
    def __init__(self, encryption_key: str):
        self.manager = EncryptionManager(encryption_key)

    def to_db(self, value: str) -> str:
        encrypted = self.manager.encrypt(value)
        return encrypted.hex()

    def from_db(self, value: str) -> str:
        encrypted = bytes.fromhex(value)
        return self.manager.decrypt(encrypted)
