            'user_id': user_id,
            'success': success,
            'ip_address': ip,
            'timestamp': datetime.utcnow().isoformat()
        }
        self.logger.info(f"LOGIN: {event}")

    def log_data_access(self, user_id: str, 
                        resource: str, 
                        action: str):
