```python
from functools import wraps
from flask import Flask, request, jsonify
import time

class SecurityMiddleware:
    def __init__(self):
        self.rate_limits = {}
        self.audit_logger = SecurityAuditLogger()
        self.anomaly_detector = AnomalyDetector()

    def require_auth(self, f):
        @wraps(f)
        def decorated(*args, **kwargs):
            token = request.headers.get('Authorization')
            if not token:
                return jsonify({'error': 'Missing token'}), 401

            try:
                payload = verify_token(
                    token.replace('Bearer ', ''),
                    'your-secret-key'
                )
                request.user = payload
            except Exception as e:
                return jsonify({'error': str(e)}), 401

            return f(*args, **kwargs)
        return decorated

    def rate_limit(self, max_requests: int = 100, 
                   window: int = 60):
        def decorator(f):
            @wraps(f)
            def decorated(*args, **kwargs):
                user_id = request.user.get('user_id')
                key = f"{user_id}:{int(time.time() / window)}"

                if key not in self.rate_limits:
                    self.rate_limits[key] = 0

                self.rate_limits[key] += 1

                if self.rate_limits[key] > max_requests:
                    return jsonify({
                        'error': 'Rate limit exceeded'
                    }), 429

                return f(*args, **kwargs)
            return decorated
        return decorator

    def log_request(self, f):
        @wraps(f)
        def decorated(*args, **kwargs):
            start_time = time.time()
            response = f(*args, **kwargs)
            duration = time.time() - start_time

            self.audit_logger.log_data_access(
                user_id=request.user.get('user_id'),
                resource=request.path,
                action=request.method
            )

            return response
        return decorated

# 使用示例
app = Flask(__name__)
security = SecurityMiddleware()

@app.route('/api/users', methods=['GET'])
@security.require_auth
@security.rate_limit(max_requests=50, window=60)
@security.log_request
def get_users():
    return jsonify({'users': []})
